<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
final class Faluss_Link {
 const STYLE='faluss-link-card',IMMERSIVE_STYLE='faluss-link-immersive',SCRIPT='faluss-link-editor';
 const NETWORKS=array('instagram','tiktok','youtube','x','linkedin','github');
 const ANNOUNCEMENTS=array('accent'=>'Accent / ink','ink'=>'Ink / white');
 const NAME_TREATMENTS=array('editorial'=>'Éditorial','strong'=>'Fort');
 const LAYOUTS=array('bubbles'=>'Bulles','inline'=>'Ligne');
 const LINK_STYLES=array('solid'=>'Plein','outline'=>'Contour');
 public static function boot(){add_shortcode('faluss_link_card',array(__CLASS__,'card_shortcode'));add_shortcode('faluss_link_appearance',array(__CLASS__,'appearance_shortcode'));add_shortcode('faluss_link_studio',array(__CLASS__,'studio_shortcode'));add_action('admin_post_faluss_link_save',array(__CLASS__,'save'));add_action('admin_post_faluss_link_save_studio',array(__CLASS__,'save_studio'));add_action('wp_ajax_faluss_link_upload_cover',array(__CLASS__,'upload_cover'));add_action('wp_enqueue_scripts',array(__CLASS__,'assets'),5);add_action('elementor/frontend/after_register_scripts',array(__CLASS__,'assets'),5);add_action('elementor/frontend/after_register_styles',array(__CLASS__,'assets'),5);add_action('elementor/widgets/register',array(__CLASS__,'widgets'));}
 public static function activate(){return Faluss_Link_Schema::install();}
 public static function assets(){wp_register_style(self::STYLE,plugins_url('assets/css/faluss-link.css',FALUSS_LINK_FILE),array(),FALUSS_LINK_VERSION);wp_register_style(self::IMMERSIVE_STYLE,plugins_url('assets/css/faluss-link-immersive.css',FALUSS_LINK_FILE),array(self::STYLE),FALUSS_LINK_VERSION);wp_register_script(self::SCRIPT,plugins_url('assets/js/faluss-link-editor.js',FALUSS_LINK_FILE),array('jquery'),FALUSS_LINK_VERSION,true);wp_localize_script(self::SCRIPT,'falussLinkCover',array('url'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('faluss_link_upload_cover')));}
 public static function card_shortcode($a=array()){return self::render_card((array)$a);}
 public static function appearance_shortcode(){return self::render_editor();}
 public static function studio_shortcode(){return self::render_studio();}
 public static function render_card($a=array()){if(!self::identity_ready())return self::empty_card(__('Carte Faluss indisponible.','faluss-link'));$a=wp_parse_args($a,array('identifier'=>'','align'=>'center','presentation'=>'compact'));$slug=''!==$a['identifier']?sanitize_title($a['identifier']):(string)get_query_var('faluss_public_profile');$p=self::published_profile($slug);if(!$p)return self::empty_card(__('Cette carte Faluss n’est pas disponible.','faluss-link'));self::enqueue_assets();$markup=self::card_markup($p,self::prefs($p['faluss_id']),self::align($a['align']));return 'immersive'===$a['presentation']?str_replace('faluss-link-card ','faluss-link-card faluss-link-card--presentation-immersive ',$markup):$markup;}
 public static function render_editor(){if(!is_user_logged_in()||!self::identity_ready())return self::empty_card(__('Connectez-vous pour personnaliser votre carte.','faluss-link'));$id=Faluss_Identity_Registry::get_active_for_wp_user(get_current_user_id());if(!$id)return self::empty_card(__('Votre identité Faluss est indisponible.','faluss-link'));self::editor_assets();$p=self::valid_prefs($id);ob_start();?><section class="faluss-link-editor"><h2><?php esc_html_e('Apparence de ma carte Faluss','faluss-link'); ?></h2><?php echo self::notice('faluss_link_notice'); ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="faluss_link_save"><?php wp_nonce_field('faluss_link_save','faluss_link_nonce');self::preference_fields($p);?><button class="faluss-link-action" type="submit"><?php esc_html_e('Enregistrer','faluss-link'); ?></button></form></section><?php return (string)ob_get_clean();}
 public static function render_studio(){if(!is_user_logged_in()||!self::identity_ready()||!class_exists('Faluss_Identity_Public_Profile'))return self::empty_card(__('Connectez-vous pour ouvrir Studio Faluss.','faluss-link'));$id=Faluss_Identity_Registry::get_active_for_wp_user(get_current_user_id());if(!$id)return self::empty_card(__('Votre identité Faluss est indisponible.','faluss-link'));self::editor_assets();$profile=Faluss_Identity_Public_Profile::studio_profile($id);$prefs=self::valid_prefs($id);ob_start();?><section class="faluss-link-studio"><header class="faluss-link-studio__header"><div class="faluss-link-studio__member"><?php if((int)$profile['avatar_attachment_id'])echo wp_get_attachment_image((int)$profile['avatar_attachment_id'],'thumbnail',false,array('alt'=>'')); ?><strong data-studio-member-name><?php echo esc_html($profile['display_name']?:__('Mon Faluss','faluss-link')); ?></strong><span data-studio-member-handle><?php echo ''===$profile['public_slug']?'@—':'@'.esc_html($profile['public_slug']); ?></span></div><?php if(''!==$profile['public_slug']&&'published'===$profile['publication_status']): ?><a href="<?php echo esc_url(home_url('/'.$profile['public_slug'])); ?>"><?php esc_html_e('Voir mon Faluss','faluss-link'); ?></a><?php endif; ?></header><form class="faluss-link-studio__form" method="post" enctype="multipart/form-data" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="faluss_link_save_studio"><?php wp_nonce_field('faluss_link_save_studio','faluss_link_studio_nonce'); ?><div class="faluss-link-studio__notice" role="status" aria-live="polite"><?php echo self::notice('faluss_studio_notice'); ?></div><nav class="faluss-link-studio__tabs" role="tablist" aria-label="<?php esc_attr_e('Sections du Studio Faluss','faluss-link'); ?>"><button id="faluss-studio-tab-profile" type="button" role="tab" aria-selected="true" aria-controls="faluss-studio-panel-profile" data-fl-tab="profile">Profil</button><button id="faluss-studio-tab-links" type="button" role="tab" aria-selected="false" aria-controls="faluss-studio-panel-links" data-fl-tab="links">Liens</button><button id="faluss-studio-tab-appearance" type="button" role="tab" aria-selected="false" aria-controls="faluss-studio-panel-appearance" data-fl-tab="appearance">Apparence</button></nav><div class="faluss-link-studio__workspace"><div id="faluss-studio-panel-profile" role="tabpanel" aria-labelledby="faluss-studio-tab-profile" data-fl-panel="profile"><label for="faluss-studio-slug"><?php esc_html_e('Identifiant public','faluss-link'); ?></label><input id="faluss-studio-slug" name="public_slug" type="text" value="<?php echo esc_attr($profile['public_slug']); ?>" pattern="[a-z0-9][a-z0-9-]{1,39}" maxlength="40" <?php echo ''!==$profile['public_slug']?'readonly':''; ?> required><p class="faluss-link-studio__hint"><?php esc_html_e('Il reste stable après sa création.','faluss-link'); ?></p><label for="faluss-studio-name"><?php esc_html_e('Nom affiché','faluss-link'); ?></label><input id="faluss-studio-name" name="display_name" type="text" maxlength="80" value="<?php echo esc_attr($profile['display_name']); ?>" required><label for="faluss-studio-bio"><?php esc_html_e('Bio courte','faluss-link'); ?></label><textarea id="faluss-studio-bio" name="bio" maxlength="280" rows="4"><?php echo esc_textarea($profile['bio']); ?></textarea><label for="faluss-studio-avatar"><?php esc_html_e('Avatar','faluss-link'); ?></label><input id="faluss-studio-avatar" name="faluss_identity_avatar" type="file" accept="image/jpeg,image/png,image/webp,image/gif"><label class="faluss-link-studio__check"><input name="publication_status" type="checkbox" value="published" <?php checked('published'===$profile['publication_status']); ?>> <?php esc_html_e('Publier mon profil','faluss-link'); ?></label></div><div id="faluss-studio-panel-links" role="tabpanel" aria-labelledby="faluss-studio-tab-links" data-fl-panel="links" hidden><fieldset><legend><?php esc_html_e('Liens publics','faluss-link'); ?></legend><?php self::link_rows($profile['links']); ?></fieldset><label for="faluss-studio-social"><?php esc_html_e('Réseaux (réseau|URL HTTPS, un par ligne)','faluss-link'); ?></label><textarea id="faluss-studio-social" name="social_links"><?php echo esc_textarea(self::social_lines($prefs['social_links'])); ?></textarea><label for="faluss-studio-social-layout"><?php esc_html_e('Affichage des réseaux','faluss-link'); ?></label><select id="faluss-studio-social-layout" name="social_layout"><?php self::options(self::LAYOUTS,$prefs['social_layout']); ?></select></div><div id="faluss-studio-panel-appearance" role="tabpanel" aria-labelledby="faluss-studio-tab-appearance" data-fl-panel="appearance" hidden><?php self::preference_fields($prefs,true); ?></div><aside class="faluss-link-studio__preview" aria-label="<?php esc_attr_e('Aperçu vivant de ma carte Faluss','faluss-link'); ?>"><h2><?php esc_html_e('Aperçu','faluss-link'); ?></h2><?php echo self::card_markup($profile,$prefs,'center',true); ?></aside></div><button class="faluss-link-action faluss-link-studio__submit" type="submit"><?php esc_html_e('Enregistrer le Studio','faluss-link'); ?></button></form></section><?php return (string)ob_get_clean();}
 public static function save(){if(!self::verify('faluss_link_nonce','faluss_link_save'))wp_die('Accès refusé.');$id=Faluss_Identity_Registry::get_active_for_wp_user(get_current_user_id());self::redirect('faluss_link_notice',$id&&self::save_preferences($id,$_POST)?'saved':'invalid');}
 public static function save_studio(){if(!self::verify('faluss_link_studio_nonce','faluss_link_save_studio'))wp_die('Accès refusé.');$id=Faluss_Identity_Registry::get_active_for_wp_user(get_current_user_id());$identity=$id&&class_exists('Faluss_Identity_Public_Profile')?Faluss_Identity_Public_Profile::save_studio_profile($id,$_POST,$_FILES):'invalid';self::redirect('faluss_studio_notice','saved'===$identity&&self::save_preferences($id,$_POST)?'saved':('taken'===$identity?'taken':'invalid'));}
 public static function upload_cover(){if(!is_user_logged_in()||!check_ajax_referer('faluss_link_upload_cover','nonce',false)||!self::identity_ready()||!Faluss_Identity_Registry::get_active_for_wp_user(get_current_user_id()))wp_send_json_error(array('message'=>'Accès refusé.'),403);if(empty($_FILES['cover'])||!is_array($_FILES['cover']))wp_send_json_error(array('message'=>'Image requise.'),400);require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/image.php';$file=$_FILES['cover'];$type=wp_check_filetype_and_ext($file['tmp_name'],$file['name']);if(empty($type['type'])||0!==strpos($type['type'],'image/'))wp_send_json_error(array('message'=>'Image invalide.'),400);$upload=wp_handle_upload($file,array('test_form'=>false,'mimes'=>array('jpg|jpeg|jpe'=>'image/jpeg','png'=>'image/png','gif'=>'image/gif','webp'=>'image/webp')));if(!empty($upload['error']))wp_send_json_error(array('message'=>'Envoi impossible.'),400);$attachment=array('post_mime_type'=>$upload['type'],'post_title'=>sanitize_file_name(pathinfo($upload['file'],PATHINFO_FILENAME)),'post_status'=>'inherit','post_author'=>get_current_user_id());$attachment_id=wp_insert_attachment($attachment,$upload['file']);if(is_wp_error($attachment_id)||!self::owned_image((int)$attachment_id,get_current_user_id()))wp_send_json_error(array('message'=>'Image invalide.'),400);wp_update_attachment_metadata($attachment_id,wp_generate_attachment_metadata($attachment_id,$upload['file']));wp_send_json_success(array('id'=>(int)$attachment_id,'url'=>wp_get_attachment_image_url($attachment_id,'medium')));}
 public static function widgets($m){if(!class_exists('Elementor\\Widget_Base')||!is_object($m)||!method_exists($m,'register'))return;require_once FALUSS_LINK_DIR.'includes/class-faluss-link-widgets.php';$m->register(new Faluss_Link_Card_Widget());$m->register(new Faluss_Link_Appearance_Widget());$m->register(new Faluss_Link_Studio_Widget());}
 public static function socials($value){$decoded=is_string($value)?json_decode($value,true):null;$items=is_array($decoded)?$decoded:(is_string($value)?preg_split('/\r\n|\r|\n/',$value):$value);$out=array();$seen=array();foreach((array)$items as $item){if(is_array($item)){$network=$item['network']??'';$url=$item['url']??'';}else{[$network,$url]=array_pad(explode('|',(string)$item,2),2,'');}$network=strtolower(trim((string)$network));$url=trim((string)$url);$parts=wp_parse_url($url);if(!in_array($network,self::NETWORKS,true)||!filter_var($url,FILTER_VALIDATE_URL)||!is_array($parts)||'https'!==strtolower($parts['scheme']??'')||isset($seen[$network.'|'.$url]))continue;$seen[$network.'|'.$url]=true;$out[]=array('network'=>$network,'url'=>$url);}return $out;}
 private static function save_preferences($id,$post){global $wpdb;$table=Faluss_Link_Schema::table();if(''===$table)return false;$pick=static function($v,$allowed,$fallback){return in_array($v,$allowed,true)?$v:$fallback;};$cover=max(0,(int)($post['cover_attachment_id']??0));if($cover&&!self::owned_image($cover,get_current_user_id()))$cover=0;$v=array('cover_attachment_id'=>$cover,'avatar_visible'=>!empty($post['avatar_visible'])?1:0,'name_weight'=>'bold','name_treatment'=>$pick(wp_unslash($post['name_treatment']??''),array_keys(self::NAME_TREATMENTS),'strong'),'available'=>!empty($post['available'])?1:0,'bio_mode'=>$pick(wp_unslash($post['bio_mode']??''),array('editorial','announcement'),'editorial'),'announcement'=>sanitize_text_field(wp_unslash($post['announcement']??'')),'announcement_variant'=>$pick(wp_unslash($post['announcement_variant']??''),array_keys(self::ANNOUNCEMENTS),'accent'),'social_links'=>wp_json_encode(self::socials(wp_unslash($post['social_links']??''))),'social_layout'=>$pick(wp_unslash($post['social_layout']??''),array_keys(self::LAYOUTS),'bubbles'),'link_style'=>$pick(wp_unslash($post['link_style']??''),array_keys(self::LINK_STYLES),'solid'));$old=self::prefs($id);$now=gmdate('Y-m-d H:i:s');if($old['faluss_id']!==$id)return false!==$wpdb->query($wpdb->prepare('INSERT INTO `'.$table.'` (faluss_id,cover_attachment_id,avatar_visible,name_weight,name_treatment,available,bio_mode,announcement,announcement_variant,social_links,social_layout,link_style,created_at,updated_at) VALUES (%s,%d,%d,%s,%s,%d,%s,%s,%s,%s,%s,%s,%s,%s)',...array_merge(array($id),array_values($v),array($now,$now))));return false!==$wpdb->update($table,$v+array('updated_at'=>$now),array('faluss_id'=>$id));}
 private static function preference_fields($p,$studio=false){$prefix=$studio?'faluss-studio-':'faluss-link-editor-';?><div class="faluss-link-preferences"><div class="faluss-link-editor__media"><label><?php esc_html_e('Photo de couverture','faluss-link'); ?></label><input class="faluss-link-editor__cover-id" name="cover_attachment_id" type="hidden" value="<?php echo (int)$p['cover_attachment_id']; ?>"><button class="faluss-link-editor__select-cover" type="button"><?php esc_html_e('Choisir une image','faluss-link'); ?></button><button class="faluss-link-editor__remove-cover" type="button"><?php esc_html_e('Retirer','faluss-link'); ?></button><div class="faluss-link-editor__cover-preview"><?php if((int)$p['cover_attachment_id'])echo wp_get_attachment_image((int)$p['cover_attachment_id'],'medium',false,array('alt'=>'')); ?></div></div><label class="faluss-link-studio__check"><input name="avatar_visible" type="checkbox" value="1" <?php checked($p['avatar_visible']); ?>> <?php esc_html_e('Afficher l’avatar','faluss-link'); ?></label><label class="faluss-link-studio__check"><input name="available" type="checkbox" value="1" <?php checked($p['available']); ?>> <?php esc_html_e('Afficher Disponible','faluss-link'); ?></label><label for="<?php echo esc_attr($prefix); ?>name"><?php esc_html_e('Traitement du nom','faluss-link'); ?></label><select id="<?php echo esc_attr($prefix); ?>name" name="name_treatment"><?php self::options(self::NAME_TREATMENTS,$p['name_treatment']); ?></select><label for="<?php echo esc_attr($prefix); ?>bio"><?php esc_html_e('Bio','faluss-link'); ?></label><select id="<?php echo esc_attr($prefix); ?>bio" name="bio_mode"><option value="editorial" <?php selected($p['bio_mode'],'editorial'); ?>><?php esc_html_e('Texte éditorial','faluss-link'); ?></option><option value="announcement" <?php selected($p['bio_mode'],'announcement'); ?>><?php esc_html_e('Annonce','faluss-link'); ?></option></select><label for="<?php echo esc_attr($prefix); ?>announcement"><?php esc_html_e('Texte de l’annonce','faluss-link'); ?></label><input id="<?php echo esc_attr($prefix); ?>announcement" name="announcement" maxlength="120" value="<?php echo esc_attr($p['announcement']); ?>"><label for="<?php echo esc_attr($prefix); ?>variant"><?php esc_html_e('Couleur de l’annonce','faluss-link'); ?></label><select id="<?php echo esc_attr($prefix); ?>variant" name="announcement_variant"><?php self::options(self::ANNOUNCEMENTS,$p['announcement_variant']); ?></select><?php if(!$studio): ?><label for="<?php echo esc_attr($prefix); ?>social"><?php esc_html_e('Réseaux (réseau|URL HTTPS, un par ligne)','faluss-link'); ?></label><textarea id="<?php echo esc_attr($prefix); ?>social" name="social_links"><?php echo esc_textarea(self::social_lines($p['social_links'])); ?></textarea><label for="<?php echo esc_attr($prefix); ?>layout"><?php esc_html_e('Affichage des réseaux','faluss-link'); ?></label><select id="<?php echo esc_attr($prefix); ?>layout" name="social_layout"><?php self::options(self::LAYOUTS,$p['social_layout']); ?></select><?php endif; ?><label for="<?php echo esc_attr($prefix); ?>links"><?php esc_html_e('Boutons de liens','faluss-link'); ?></label><select id="<?php echo esc_attr($prefix); ?>links" name="link_style"><?php self::options(self::LINK_STYLES,$p['link_style']); ?></select></div><?php }
 private static function link_rows($links){$links=is_array($links)?$links:array();while(count($links)<8)$links[]=array('label'=>'','url'=>'','position'=>count($links)+1);foreach($links as $i=>$l): ?><div class="faluss-link-studio__link-row"><input name="links[<?php echo (int)$i; ?>][position]" type="number" min="1" max="8" value="<?php echo (int)$l['position']; ?>" aria-label="<?php esc_attr_e('Position','faluss-link'); ?>"><input name="links[<?php echo (int)$i; ?>][label]" type="text" maxlength="80" value="<?php echo esc_attr($l['label']); ?>" placeholder="<?php esc_attr_e('Libellé','faluss-link'); ?>"><input name="links[<?php echo (int)$i; ?>][url]" type="url" maxlength="2048" value="<?php echo esc_attr($l['url']); ?>" placeholder="https://"></div><?php endforeach; }
 private static function card_markup($p,$pref,$align='center',$preview=false){$cover=(int)$pref['cover_attachment_id'];$avatar=(int)$p['avatar_attachment_id'];$has_cover=$cover>0;$has_avatar=(int)$pref['avatar_visible']&&$avatar>0;ob_start();?><article class="faluss-link-card faluss-link-card--align-<?php echo esc_attr(self::align($align)); ?> faluss-link-card--links-<?php echo esc_attr($pref['link_style']); ?> faluss-link-card--cover-<?php echo $has_cover?'yes':'no'; ?> faluss-link-card--avatar-<?php echo $has_avatar?'yes':'no'; ?>"><div class="faluss-link-card__cover" <?php echo $has_cover?'':'hidden'; ?>><?php if($has_cover)echo wp_get_attachment_image($cover,'large',false,array('alt'=>'')); ?></div><div class="faluss-link-card__body"><span class="faluss-link-card__availability" <?php echo (int)$pref['available']?'':'hidden'; ?>><i></i>Disponible</span><div class="faluss-link-card__avatar" <?php echo $has_avatar?'':'hidden'; ?>><?php if($has_avatar)echo wp_get_attachment_image($avatar,'medium',false,array('alt'=>'')); ?></div><h2 class="faluss-link-card__name faluss-link-card__name--<?php echo esc_attr($pref['name_treatment']); ?>"><?php echo esc_html($p['display_name']?:__('Mon Faluss','faluss-link')); ?></h2><p class="faluss-link-card__handle"><?php echo ''===$p['public_slug']?'@—':'@'.esc_html($p['public_slug']); ?></p><p class="faluss-link-card__announcement faluss-link-card__announcement--<?php echo esc_attr($pref['announcement_variant']); ?>" <?php echo 'announcement'===$pref['bio_mode']&&''!==$pref['announcement']?'':'hidden'; ?>><?php echo esc_html($pref['announcement']); ?></p><p class="faluss-link-card__bio" <?php echo 'announcement'===$pref['bio_mode']?'hidden':''; ?>><?php echo esc_html($p['bio']); ?></p><nav class="faluss-link-card__social faluss-link-card__social--<?php echo esc_attr($pref['social_layout']); ?>" aria-label="<?php esc_attr_e('Réseaux sociaux','faluss-link'); ?>"><?php foreach(self::socials($pref['social_links']) as $s): ?><a href="<?php echo esc_url($s['url']); ?>" target="_blank" rel="noopener noreferrer nofollow" aria-label="<?php echo esc_attr(ucfirst($s['network'])); ?>"><?php echo self::icon($s['network']); ?></a><?php endforeach; ?></nav><div class="faluss-link-card__links"><?php foreach((array)$p['links'] as $l):if(!empty($l['url'])): ?><a class="faluss-link-card__link" href="<?php echo esc_url($l['url']); ?>" target="_blank" rel="noopener noreferrer nofollow"><?php echo esc_html($l['label']??$l['url']); ?></a><?php endif;endforeach; ?></div></div></article><?php return (string)ob_get_clean();}
 private static function published_profile($slug){global $wpdb;if(''===(string)$slug)return null;$table=Faluss_Identity_Schema::get_public_profiles_table();$r=$wpdb->get_row($wpdb->prepare('SELECT faluss_id,public_slug,display_name,bio,avatar_attachment_id,external_links FROM `'.$table.'` WHERE public_slug=%s AND publication_status=%s',sanitize_title($slug),'published'),ARRAY_A);if(!is_array($r))return null;$r['links']=json_decode($r['external_links'],true);return $r;}
 private static function prefs($id){global $wpdb;$d=array('faluss_id'=>'','cover_attachment_id'=>0,'avatar_visible'=>1,'name_weight'=>'bold','name_treatment'=>'strong','available'=>0,'bio_mode'=>'editorial','announcement'=>'','announcement_variant'=>'accent','social_links'=>'[]','social_layout'=>'bubbles','link_style'=>'solid');$r=$wpdb->get_row($wpdb->prepare('SELECT * FROM `'.Faluss_Link_Schema::table().'` WHERE faluss_id=%s',$id),ARRAY_A);return is_array($r)?array_merge($d,$r):$d;}
 private static function valid_prefs($id){$p=self::prefs($id);if((int)$p['cover_attachment_id']&&!self::owned_image((int)$p['cover_attachment_id'],get_current_user_id()))$p['cover_attachment_id']=0;return $p;}
 private static function verify($field,$action){return is_user_logged_in()&&isset($_POST[$field])&&wp_verify_nonce(sanitize_text_field(wp_unslash($_POST[$field])),$action);}
 private static function redirect($key,$notice){$url=wp_validate_redirect(wp_get_referer(),home_url('/'));wp_safe_redirect(add_query_arg($key,$notice,$url));exit;}
 private static function notice($key){$v=isset($_GET[$key])?sanitize_key(wp_unslash($_GET[$key])):'';$m=array('saved'=>__('Studio enregistré.','faluss-link'),'taken'=>__('Cet identifiant public n’est pas disponible.','faluss-link'),'invalid'=>__('Nous ne pouvons pas enregistrer le Studio.','faluss-link'));return isset($m[$v])?'<p class="faluss-link-notice">'.esc_html($m[$v]).'</p>':'';}
 private static function social_lines($v){$out=array();foreach(self::socials($v) as $s)$out[]=$s['network'].'|'.$s['url'];return implode("\n",$out);}
 private static function options($options,$selected){foreach($options as $k=>$v): ?><option value="<?php echo esc_attr($k); ?>" <?php selected($selected,$k); ?>><?php echo esc_html($v); ?></option><?php endforeach;}
 private static function align($v){return in_array($v,array('left','center','right'),true)?$v:'center';}
 private static function identity_ready(){return class_exists('Faluss_Identity_Schema')&&class_exists('Faluss_Identity_Registry')&&!empty(Faluss_Identity_Schema::get_status()['ready']);}
 private static function enqueue_assets(){if(!wp_style_is(self::STYLE,'registered'))self::assets();wp_enqueue_style(self::STYLE);wp_enqueue_style(self::IMMERSIVE_STYLE);}
 private static function editor_assets(){self::enqueue_assets();wp_enqueue_script(self::SCRIPT);}
 private static function owned_image($attachment_id,$user_id){$a=get_post((int)$attachment_id);return $a instanceof WP_Post&&(int)$a->post_author===(int)$user_id&&0===strpos((string)$a->post_mime_type,'image/');}
 private static function empty_card($message){return '<div class="faluss-link-card faluss-link-card--empty" role="status">'.esc_html($message).'</div>';}
 private static function icon($network){$paths=array('instagram'=>'<rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r="1"/>','tiktok'=>'<path d="M14 4v10.5a4 4 0 1 1-3-3.87"/><path d="M14 4c1 2.4 2.7 3.8 5 4"/>','youtube'=>'<path fill="currentColor" stroke="none" d="M21 12s0-4-1-5-7-1-8-1-7 0-8 1-1 5-1 5 0 4 1 5 7 1 8 1 7 0 8-1 1-5 1-5z"/><path fill="#FFFDF5" stroke="none" d="m10 9 5 3-5 3z"/>','x'=>'<path d="M5 4l14 16M19 4 5 20"/>','linkedin'=>'<path d="M6 9v9M6 6v.1M10 18v-5a3 3 0 0 1 6 0v5M10 12V9"/>','github'=>'<path d="M9 19c-5 1.5-5-2.5-7-3m14 6v-3.9c0-1.1.1-1.8-.5-2.5 2-.2 4-1 4-4.5 0-1-.3-1.8-.8-2.5.1-.2.4-1.2-.1-2.5 0 0-.7-.2-2.5 1a8.6 8.6 0 0 0-4.5 0c-1.8-1.2-2.5-1-2.5-1-.5 1.3-.2 2.3-.1 2.5-.5.7-.8 1.5-.8 2.5 0 3.5 2 4.3 4 4.5-.4.4-.6 1-.6 2v3.9"/>');return '<svg aria-hidden="true" viewBox="0 0 24 24">'.$paths[$network].'</svg>';}
